/// <reference types="vitest" />
/**
 * Vite config for the tce-main-street single-game launcher.
 *
 * AUTO-GENERATED by scripts/game-repo-scaffold.ts — edit that template rather
 * than this file so a re-scaffold does not clobber local changes.
 *
 * LOCAL SURGICAL ADDITIONS not present in the scaffold template (precedent:
 * MS-0MV8M9IAF000KPNY): the exported `CLI_TEST_FILES` + `unit-cli` project
 * (MS-0MV5PNIPO00940KG), the `unit`/`unit-cli` `sequence.groupOrder` split
 * with `unit-cli` first, the `projectCoverageReporter` guard
 * (MS-0MVK37SK5009M0NG), and the engine-checkout preflight registered as the
 * root `test.globalSetup` (MS-0MVO26G5H0054SNV). A re-scaffold drops all of
 * these; the guards in
 * `tests/main-street/vitest-cli-project-isolation.test.ts`,
 * `tests/main-street/testing-docs-projects.test.ts` and
 * `tests/main-street/vite-config-engine-check-guard.test.ts` fail loudly if
 * they are lost.
 *
 * The engine toolchain (the config-driven game-discovery plugin and the core
 * path aliases) is imported from the sibling core checkout at `./core`.
 */
import { defineConfig } from 'vite';
import path from 'path';
import fs from 'fs';
import {
  gameDiscoveryPlugin,
  resolveCoreAliases,
} from './core/scripts/vite-game-discovery-plugin';
import { DEV_WATCH_IGNORE_PATTERNS } from './core/scripts/vite-transcript-plugin';
import { writeCardTestResults } from './tests/main-street/cards/CardTestResultWriter';
import { createProjectCoverageReporter } from './tests/tooling/vitest-project-coverage-reporter';
import { computeCsvChecksum } from './src/CsvChecksum';

const coreRoot = path.resolve(__dirname, './core');
const pkg = JSON.parse(
  fs.readFileSync(path.resolve(__dirname, 'package.json'), 'utf-8'),
);
/**
 * Production base path for the GitHub Pages project site.
 *
 * Derived generically from the package name (the last path segment, so a
 * scoped package like `@scope/game` yields `/game/`), with a `PAGES_BASE`
 * environment override for forks or custom domains. No hard-coded repository
 * name appears outside this derivation, so a re-scaffold (which regenerates
 * this file from `core/scripts/game-repo-scaffold.ts`) never regresses it.
 */
function resolvePagesBase(): string {
  const override = process.env.PAGES_BASE;
  if (override && override.trim() !== '') {
    const trimmed = override.trim();
    return trimmed === '/' ? '/' : `/${trimmed.replace(/^\/+|\/+$/g, '')}/`;
  }
  const name = String(pkg.name ?? 'app');
  const segment = name.includes('/') ? name.slice(name.lastIndexOf('/') + 1) : name;
  return `/${segment}/`;
}
// A game repo's only preset is ./configs/game.json; the
// plugin default (core-only) applies to the core repo. GAMES_CONFIG can
// still override for an ad-hoc build.
const presetEnv = {
  ...process.env,
  GAMES_CONFIG: process.env.GAMES_CONFIG ?? 'game',
};

/**
 * Subprocess/render-heavy CLI tests that cold-start a `vite-node` process (or,
 * for `storyline-graph-svg`, a Playwright Chromium render) per test file.
 *
 * Under Vitest file-level parallelism these contend with each other — and with
 * the rest of the unit suite — for CPU and the Vite transform pipeline; the
 * spawned CLI then fails spuriously (`expected 1 to be +0`) even though the
 * production CLI is fine (MS-0MV5PNIPO00940KG). They are therefore moved out of
 * the `unit` project into the serialized `unit-cli` project below, which runs
 * in its own (first) `sequence.groupOrder` group.
 *
 * Exported so the project-selection guards can assert the *real* set instead
 * of a copy (`tests/main-street/vitest-cli-project-isolation.test.ts`).
 */
export const CLI_TEST_FILES = [
  'tests/main-street/validate-storylines.test.ts',
  'tests/main-street/storyline-graph.test.ts',
  'tests/main-street/storyline-author.test.ts',
  'tests/main-street/storyline-graph-svg.test.ts',
  'tests/main-street/harness-cli.test.ts',
];

/**
 * Dev-server middleware that persists browser card-test results into
 * `src/card-data.csv`.
 *
 * Browser tests run in Chromium and cannot write files directly, so they POST
 * their results to `/__card-results`; this Node-side handler does the
 * idempotent, atomic write via the shared result writer.
 */
function cardResultsWriterPlugin() {
  return {
    name: 'card-results-writer',
    configureServer(server: import('vite').ViteDevServer) {
      server.middlewares.use('/__card-results', (req, res) => {
        if (req.method !== 'POST') {
          res.statusCode = 405;
          res.end('POST only');
          return;
        }
        let body = '';
        req.on('data', (chunk: Buffer | string) => {
          body += chunk;
        });
        req.on('end', () => {
          try {
            const payload = JSON.parse(body) as {
              results: Parameters<typeof writeCardTestResults>[1];
              targets?: Parameters<typeof writeCardTestResults>[2];
            };
            const csvPath = path.resolve(__dirname, 'src/card-data.csv');
            const result = writeCardTestResults(
              csvPath,
              payload.results,
              payload.targets,
            );
            // Keep the SVG change-detection checksum in sync with the CSV so
            // the committed artifacts agree (the checksum covers the whole file).
            const checksum = computeCsvChecksum(fs.readFileSync(csvPath, 'utf-8'));
            const checksumPath = path.resolve(
              __dirname,
              'public/assets/games/main-street/svg/cards/csv-checksum.json',
            );
            if (fs.existsSync(path.dirname(checksumPath))) {
              fs.writeFileSync(checksumPath, JSON.stringify({ checksum }) + '\n', 'utf8');
            }
            res.statusCode = 200;
            res.setHeader('content-type', 'application/json');
            res.end(JSON.stringify({ ...result, checksum }));
          } catch (error) {
            res.statusCode = 500;
            res.end(String(error));
          }
        });
      });
    },
  };
}

export default defineConfig(({ mode }) => ({
  define: {
    __APP_VERSION__: JSON.stringify(pkg.version),
  },
  // Electron loads the bundle over file://, so relative asset URLs are required.
  // Electron uses file:// → relative paths; production (GitHub Pages)
  // uses the project path derived from the package name; dev uses root
  // (localhost serves at /).
  base: mode === 'electron' ? './' : mode === 'production' ? resolvePagesBase() : '/',
  plugins: [
    // Reads ./configs/game.json and generates
    // 'virtual:game-registry' (Gym from the core + this one game).
    gameDiscoveryPlugin({ projectRoot: __dirname, coreRoot, env: presetEnv }),
    cardResultsWriterPlugin(),
  ],
  resolve: {
    alias: resolveCoreAliases(coreRoot),
    // Shared engine/launcher runtime deps must resolve to exactly ONE copy:
    // this repo's `node_modules`. Core-owned modules live in the `./core`
    // submodule, which normally has no `node_modules` of its own — but a
    // single `npm install` *inside* `core/` (for example from a core-repo
    // session) creates a second `phaser`, and every core-owned module then
    // resolves its own copy. The duplicate is a different module id, so the
    // Node-environment unit tests' `vi.mock('phaser')` — resolved from the
    // test file against the root copy — stops applying and real Phaser is
    // evaluated during collection (`ReferenceError: window is not defined`,
    // 17 files, MS-0MVK3SF54006Y6A6). Deduping pins both sides to the root
    // copy and mirrors `resolve.dedupe` in `core/vite.config.ts`.
    dedupe: ['phaser', 'tone'],
  },
  build: {
    outDir: 'dist',
    sourcemap: true,
  },
  server: {
    port: 3000,
    open: false,
    watch: {
      // Exclude dev-output trees and .worklog/ worktree checkouts from the
      // file watcher. Recursive watches into .worklog/worktrees exhaust
      // fs.inotify.max_user_watches (ENOSPC), crashing the dev server
      // on startup.
      ignored: [...DEV_WATCH_IGNORE_PATTERNS],
    },
  },
  test: {
    // Engine-checkout preflight (MS-0MVO26G5H0054SNV) — LOCAL SURGICAL
    // ADDITION. Every Vitest invocation in this repo (`npm test`, the
    // changed-scope gate's direct `npx vitest run <files>`, the dev-push
    // browser gate) inherits this root setting, so each run states which
    // `./core` commit it composed and fails loudly when that checkout is
    // behind (or diverged from) `configs/engine-pin.json` instead of
    // returning a green suite that never saw the pinned engine. The check is
    // offline (local commit graph only) and sub-second; the config-level
    // hook is the only place that also covers direct Vitest runs, which a
    // `pretest`-only hook would miss. Manual: `npm run engine:check`.
    globalSetup: ['./tests/tooling/engine-checkout-precheck.ts'],
    // Loud zero-coverage guard (MS-0MVK37SK5009M0NG): fails the run when a
    // project that was scheduled contributed no files — or fewer files than the
    // run intended — naming the project and the files that never executed.
    // Without it, Vitest's silent drop of a later `sequence.groupOrder` group
    // (see the `unit` / `unit-cli` comments below) reads as a green gate.
    //
    // The `default` reporter stays wired: the test-skill cache, the tripwire
    // greps and human operators all read its `Test Files … passed` summary.
    // Note: an explicit `--reporter=` on the CLI replaces this list, so gate
    // runs must not pass one (documented in docs/dev/testing.md).
    reporters: [['default', {}], createProjectCoverageReporter()],
    projects: [
      // A game repo ships only its own unit suite; browser/teacher profiles
      // live in the launcher distribution.
      {
        extends: true,
        test: {
          name: 'unit',
          globals: true,
          environment: 'node',
          // Group 1: runs AFTER the serialized `unit-cli` group (group 0).
          //
          // Vitest executes `sequence.groupOrder` groups sequentially and
          // aborts the loop when one group's pool run rejects — which a
          // `[vitest-worker]: Timeout calling "onTaskUpdate"` transient does. A
          // group that has not started yet is then silently dropped with the
          // run still reporting the executed files as green
          // (MS-0MVK37SK5009M0NG). The parallel group is the one that can
          // reject under CPU contention, so it must never precede another
          // group: `unit-cli` runs first and cannot be the dropped one.
          sequence: { groupOrder: 1 },
          // The replay CLI subprocess inherits this: it must resolve the
          // repo's single-game preset to register the game's adapter.
          env: { GAMES_CONFIG: 'game' },
          include: ['tests/**/*.test.ts'],
          // Browser tests have their own project; the subprocess/render-heavy
          // CLI tests run in the serialized `unit-cli` project below instead,
          // so they never contend with the parallel unit workers
          // (MS-0MV5PNIPO00940KG).
          exclude: ['tests/**/*.browser.test.ts', ...CLI_TEST_FILES],
          testTimeout: 15_000,
          maxWorkers: 4,
        },
      },
      // Serialized subprocess/render-heavy CLI tests (MS-0MV5PNIPO00940KG).
      //
      // Each file cold-starts `vite-node` (or a Playwright Chromium render) and
      // asserts a zero exit code. Running them in the parallel `unit` pool makes
      // concurrent cold Vite compilations contend for CPU and the transform
      // pipeline, intermittently yielding a spurious non-zero CLI exit. This
      // project runs with `fileParallelism: false` (one file at a time) in its
      // own `sequence.groupOrder` group (0), so it never shares a pool run with
      // the parallel suites. Mirrors the core `replay-e2e` isolation pattern
      // (cold Vite compilation under CPU contention).
      //
      // Why group 0 (before `unit`, group 1) rather than after it
      // (MS-0MVK37SK5009M0NG): Vitest 3.2.7 runs groups sequentially with no
      // per-group error isolation, so a rejection in an earlier group's pool
      // run silently drops every later group. Running the CLI group first makes
      // its five files unskippable, while keeping them serialized and free of
      // contention (nothing else is running yet).
      {
        extends: true,
        test: {
          name: 'unit-cli',
          globals: true,
          environment: 'node',
          // The spawned CLI subprocesses inherit this: they must resolve the
          // repo's single-game preset to register the game's adapter.
          env: { GAMES_CONFIG: 'game' },
          include: CLI_TEST_FILES,
          fileParallelism: false,
          sequence: { concurrent: false, groupOrder: 0 },
          testTimeout: 180_000,
        },
      },
      // Browser integration project: real Phaser MainStreetScene in headless
      // Chromium (Playwright). Runs serially because the browser/GPU context is
      // shared and sensitive. Includes the card-level browser suite under
      // tests/main-street/cards/browser/.
      {
        extends: true,
        test: {
          name: 'browser',
          globals: true,
          include: ['tests/**/*.browser.test.ts'],
          fileParallelism: false,
          sequence: { concurrent: false },
          testTimeout: 60_000,
          browser: {
            enabled: true,
            provider: 'playwright',
            headless: true,
            instances: [{ browser: 'chromium' }],
            viewport: { width: 900, height: 700 },
            isolate: true,
          },
        },
      },
    ],
  },
}));
